export namespace scorecalc {
    /**
     * GetLeaderboardParams specifies sorting, filtering, and pagination query params.
     */
    export interface GetLeaderboardParams {
        /**
         * "points", "rating", "avgPosition", "avgPointsPerSeason"
         */
        SortBy: string

        /**
         * search participant name or @username
         */
        Search: string

        /**
         * filter by class tier e.g. "G1", "G2", "G3", "OP"
         */
        ClassTier: string

        /**
         * calendar year cutoff (defaults to current UTC year unless allTime is true)
         */
        Year: number

        /**
         * when true, aggregates across all seasons (year = 0)
         */
        AllTime: boolean

        /**
         * pagination limit
         */
        Limit: number

        /**
         * pagination offset
         */
        Offset: number
    }

    /**
     * GetTeamLeaderboardParams specifies sorting, filtering, and pagination query params for teams.
     */
    export interface GetTeamLeaderboardParams {
        /**
         * "points", "avgRank", "avgPoints"
         */
        SortBy: string

        /**
         * search team name or @slug
         */
        Search: string

        /**
         * calendar year (defaults to current UTC year unless allTime is true)
         */
        Year: number

        /**
         * when true, aggregates across all seasons (year = 0)
         */
        AllTime: boolean

        Limit: number
        Offset: number
    }

    /**
     * LeaderboardEntry represents one row on the overall leaderboard.
     */
    export interface LeaderboardEntry {
        rank: number
        userId: string
        name: string
        slug: string
        image: string
        classTier: string
        totalPoints: number
        averagePosition: number
        averagePointsPerSeason: number
        eventsParticipated: number
        racesParticipated: number
        wins: number
        rating: number
        ratingDeviation: number
        ratingVolatility: number
        peakRating: number
        seasonRatingDelta: number
        isProvisional: boolean
    }

    /**
     * LeaderboardResponse holds paginated leaderboard rows along with total count.
     */
    export interface LeaderboardResponse {
        entries: LeaderboardEntry[]
        total: number
        year: number
        availableYears: number[]
        calculatedAt: string
    }

    /**
     * RecalculateRatingsResponse reports the outcome of a full Glicko-2 historical recalculation.
     */
    export interface RecalculateRatingsResponse {
        racesProcessed: number
        resultsUpdated: number
        usersRated: number
        yearsProcessed: number[]
        calculatedAt: string
    }

    /**
     * TeamLeaderboardEntry represents one row on the global team leaderboard.
     */
    export interface TeamLeaderboardEntry {
        rank: number
        teamId: string
        name: string
        slug: string
        logo: string
        memberCount: number
        teamEventsParticipated: number
        teamTotalPoints: number
        teamAveragePoints: number
        teamEventRankAverage: number
        memberPointsAverage: number
        memberRankingAverage: number
        memberAvgPointsPerEvent: number
        /**
         * "TEAM_EVENTS" | "MEMBER_AVERAGE"
         */
        rankingSource: string
    }

    /**
     * TeamLeaderboardResponse holds paginated team leaderboard rows along with total count.
     */
    export interface TeamLeaderboardResponse {
        entries: TeamLeaderboardEntry[]
        total: number
        year: number
        availableYears: number[]
        rankingSource: string
        calculatedAt: string
    }

    export class ServiceClient {
        private baseClient: BaseClient

        constructor(baseClient: BaseClient) {
            this.baseClient = baseClient
            this.GetLeaderboard = this.GetLeaderboard.bind(this)
            this.GetTeamLeaderboard = this.GetTeamLeaderboard.bind(this)
            this.RecalculateRatings = this.RecalculateRatings.bind(this)
        }

        /**
         * GetLeaderboard returns global leaderboard rankings with filtering, sorting, and pagination.
         * Results are cut off by calendar year (defaulting to current UTC year) and cached for 10 minutes.
         */
        public async GetLeaderboard(params: GetLeaderboardParams): Promise<LeaderboardResponse> {
            // Convert our params into the objects we need for the request
            const query = makeRecord<string, string | string[]>({
                allTime:   String(params.AllTime),
                classTier: params.ClassTier,
                limit:     String(params.Limit),
                offset:    String(params.Offset),
                search:    params.Search,
                sortBy:    params.SortBy,
                year:      String(params.Year),
            })

            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/api/leaderboard`, undefined, {query})
            return await resp.json() as LeaderboardResponse
        }

        /**
         * GetTeamLeaderboard returns global team standings for a season or all-time.
         */
        public async GetTeamLeaderboard(params: GetTeamLeaderboardParams): Promise<TeamLeaderboardResponse> {
            // Convert our params into the objects we need for the request
            const query = makeRecord<string, string | string[]>({
                allTime: String(params.AllTime),
                limit:   String(params.Limit),
                offset:  String(params.Offset),
                search:  params.Search,
                sortBy:  params.SortBy,
                year:    String(params.Year),
            })

            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/api/team-leaderboard`, undefined, {query})
            return await resp.json() as TeamLeaderboardResponse
        }

        /**
         * RecalculateRatings allows a SITE_ADMIN to manually trigger a full historical
         * Glicko-2 backfill and recalculation across all races.
         */
        public async RecalculateRatings(): Promise<RecalculateRatingsResponse> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("POST", `/api/admin/ratings/recalculate`)
            return await resp.json() as RecalculateRatingsResponse
        }
    }
}

